#!/usr/bin/env node
'use strict';

const fs = require('fs');

function u16(b, o, le) { return le ? b.readUInt16LE(o) : b.readUInt16BE(o); }
function u32(b, o, le) { return le ? b.readUInt32LE(o) : b.readUInt32BE(o); }
function u64(b, o, le) { return le ? b.readBigUInt64LE(o) : b.readBigUInt64BE(o); }

function extract(path) {
  const buf = fs.readFileSync(path);
  if (buf.length < 52 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const cls = buf[4];
  const le = buf[5] !== 2;
  if (cls !== 1 && cls !== 2) throw new Error('unsupported ELF class');

  const is64 = cls === 2;
  const phoff = is64 ? Number(u64(buf, 32, le)) : u32(buf, 28, le);
  const phentsize = u16(buf, is64 ? 54 : 42, le);
  const phnum = u16(buf, is64 ? 56 : 44, le);

  const out = Object.create(null);
  const PT_LOAD = 1;

  for (let n = 0; n < phnum; n++) {
    const ph = phoff + n * phentsize;
    if (ph + phentsize > buf.length) break;
    const type = u32(buf, ph, le);
    if (type !== PT_LOAD) continue;

    let offset, vaddr, filesz;
    if (is64) {
      offset = u64(buf, ph + 8, le);
      vaddr = u64(buf, ph + 16, le);
      filesz = u64(buf, ph + 32, le);
    } else {
      offset = BigInt(u32(buf, ph + 4, le));
      vaddr = BigInt(u32(buf, ph + 8, le));
      filesz = BigInt(u32(buf, ph + 16, le));
    }

    const off = Number(offset);
    const vs = vaddr;
    const end = Number(filesz);
    const limit = Math.min(end, Math.max(0, buf.length - off));

    for (let i = 0; i + 4 <= limit; i += 4) {
      const value = le ? buf.readUInt32LE(off + i) : buf.readUInt32BE(off + i);
      out[(vs + BigInt(i)).toString()] = value;
    }
  }

  return out;
}

const file = process.argv[2];
if (!file) {
  console.error('usage: node extract.js <elf-file>');
  process.exit(1);
}
process.stdout.write(JSON.stringify(extract(file)));
EOF

